import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=";",
        quotechar='"',
        doublequote=True,
    )

    columns = next(reader, None)
    if columns is None:
        return {"columns": [], "rows": []}

    rows = list(reader)
    width = max(17, len(columns), max((len(row) for row in rows), default=0))

    # Name fields beyond the header without changing existing column names.
    used_names = set(columns)
    while len(columns) < width:
        base = f"column_{len(columns) + 1}"
        name = base
        suffix = 2
        while name in used_names:
            name = f"{base}_{suffix}"
            suffix += 1
        columns.append(name)
        used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
